function AmountForm({
  label,
  hint,
  initial,
  allowZero,
  t,
  busy,
  error,
  onSubmit,
  onCancel,
}: {
  label: string
  hint?: string
  initial: string
  allowZero?: boolean
  t: T
  busy: boolean
  error: string
  onSubmit: (cents: number) => void
  onCancel: () => void
}) {
  const [value, setValue] = useState(initial)
  const [local, setLocal] = useState('')
  return (
    <form
      className="led-form"
      onSubmit={(e) => {
        e.preventDefault()
        const cents = parseAmount(value || '0')
        if (cents === null || (!allowZero && cents === 0)) return setLocal('invalid_amount')
        setLocal('')
        onSubmit(cents)
      }}
    >
      <Field label={`${label} · ${BASE_CURRENCY}`} hint={hint}>
        <input inputMode="decimal" autoFocus value={value} onChange={(e) => setValue(e.target.value)} placeholder="0.00" />
      </Field>
      <Actions t={t} busy={busy} error={local || error} onCancel={onCancel} />
    </form>
  )
}

function RateForm({
  currency,
  rate,
  t,
  busy,
  error,
  onSubmit,
  onCancel,
}: {
  currency: Currency
  rate: number
  t: T
  busy: boolean
  error: string
  onSubmit: (rate: number) => void
  onCancel: () => void
}) {
  const [value, setValue] = useState(rate ? String(rate) : '')
  const [local, setLocal] = useState('')
  return (
    <form
      className="led-form"
      onSubmit={(e) => {
        e.preventDefault()
        const next = Number(value)
        if (!/^\d+(\.\d{1,6})?$/.test(value.trim()) || !(next > 0) || next > 10_000) return setLocal('invalid_amount')
        setLocal('')
        onSubmit(next)
      }}
    >
      <Field label={`1 ${currency} = ? ${BASE_CURRENCY}`} hint={t('ratesHint')}>
        <input inputMode="decimal" autoFocus value={value} onChange={(e) => setValue(e.target.value)} />
      </Field>
      <Actions t={t} busy={busy} error={local || error} onCancel={onCancel} />
    </form>
  )
}

import type { LedgerClient, LedgerData, LedgerResult } from './domain'
const base = import.meta.env.VITE_LOVBASE_URL as string
const workspace = import.meta.env.VITE_LOVBASE_WORKSPACE as string
const token = import.meta.env.VITE_LOVBASE_TOKEN as string
async function call<T>(body?: unknown): Promise<T> {
  const response = await fetch(`${base}/api/data/${workspace}/ledger`, {
    method: body ? 'POST' : 'GET',
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
    ...(body ? { body: JSON.stringify(body) } : {}),
  })
  const result = await response.json()
  if (!response.ok) throw new Error(result.error || result.message || 'request_failed')
  return result as T
}
export const ledgerClient: LedgerClient = {
  read: () => call<LedgerData>(),
  command: (command) => call<LedgerResult>(command),
}

