  --led-ink: #1f2b4d;
  --led-in: #2f7a55;
  --led-out: #b4472f;
  --led-warn: #c28a1d;
  --led-figure: 'Iowan Old Style', 'Palatino Linotype', Palatino, Georgia, 'Songti SC', serif;
  color: var(--led-fg);
  font-family: Inter, Geist, system-ui, -apple-system, 'PingFang SC', sans-serif;
  font-size: 13px;
  line-height: 1.5;
  text-align: left;
  color-scheme: light;
  box-sizing: border-box;
  display: flex;
  background: var(--led-bg);
}
.ledger-viewport {
  display: flex;
  height: 100dvh;
  overflow: hidden;
}
.ledger-app:not(.led-modal) {
  flex: 1;
  height: 100%;
  min-height: 0;
  min-width: 0;
  overflow: hidden;
}
.ledger-app * {
  box-sizing: border-box;
}
.ledger-app button,
.ledger-app input,
.ledger-app [data-slot='select-trigger'] {
  font: inherit;
}
.ledger-app button {
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 1px solid var(--led-line);
  border-radius: 8px;
